#!/usr/bin/env python3
"""Build self-contained demos from trained parameters and measured results."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CSS='''*{box-sizing:border-box}body{margin:0;background:#f7f8f3;color:#192a27;font:15px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;overflow-wrap:anywhere}main{max-width:1100px;margin:auto;padding:35px 26px}a{color:#225d48}h1{font-size:38px;line-height:1.3;margin:16px 0}h2{font-size:20px}p,.muted{color:#66756f}.label{font-size:12px;letter-spacing:2px;color:#225d48}.badge{display:inline-block;background:#e9f0e8;color:#225d48;border-radius:25px;padding:5px 12px;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.card{padding:24px;background:white;border:1px solid #d8e0d9;border-radius:10px;min-width:0}input,textarea,select,button{font:inherit}textarea,input{width:100%;border:1px solid #d8e0d9;border-radius:6px;padding:12px}textarea{min-height:110px}button{background:#225d48;color:white;border:0;border-radius:5px;padding:10px 20px;cursor:pointer;margin:10px 6px 10px 0}select{border:1px solid #d8e0d9;border-radius:5px;padding:8px;max-width:100%}button:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #bb8c3c;outline-offset:3px}.metric{font-size:38px;color:#225d48}.warning{border-left:3px solid #a7752d;padding-left:14px;font-size:13px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:9px;text-align:left;border-bottom:1px solid #d8e0d9;white-space:nowrap}.trace{padding:12px 0;border-bottom:1px solid #d8e0d9;font-size:13px}.footer{padding-top:24px;font-size:12px}.full{grid-column:1/-1}@media(max-width:700px){.grid{grid-template-columns:1fr}h1{font-size:29px}}'''

def build(project,title,subtitle,body,js,data):
 encoded=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body><main><a href="../../index.html">← 于跃作品集</a><div class="label">LOCAL AI · EXPERIMENTS · EVIDENCE</div><h1>{title}</h1><p>{subtitle}</p><span class="badge">AI 辅助实现 · 可运行研究原型</span><div class="grid" style="margin-top:25px">{body}</div><p class="footer">代码与评测由 AI 辅助搭建；本人独立修改/验证贡献待记录。不是 ByteDance 官方作品或生产成果。</p></main><script id="data" type="application/json">{encoded}</script><script>'use strict';const data=JSON.parse(document.getElementById('data').textContent);const $=id=>document.getElementById(id);const text=(tag,v)=>{{const e=document.createElement(tag);e.textContent=String(v??'—');return e;}};function table(id,rows){{const el=$(id);el.replaceChildren();rows.forEach(v=>{{const tr=text('tr','');v.forEach(x=>tr.append(text('td',x)));el.append(tr);}});}}{js}</script></body></html>'''
 (ROOT/'projects'/project/'demo.html').write_text(html,encoding='utf-8')

def main():
 def read(p,n):return json.loads((ROOT/'projects'/p/'artifacts'/n).read_text())
 tg={'model':read('textguard','model.json'),'results':read('textguard','results.json')}
 body='''<section class="card"><h2>实际模型推断 · 英文短文本</h2><textarea id="input" aria-label="输入英文短文本">Claim your free prize now call this number</textarea><button id="predict">运行本地分类</button><select id="examples" aria-label="示例"></select><p id="status" role="status"></p><div class="metric" id="prob"></div><div id="terms"></div><p class="warning">不上传输入。概率未校准，英文旧短信研究数据，不用于安全拦截；中文/无词表证据需人工复核。</p></section><section class="card"><h2>固定留出测试 · 不是演示输入评分</h2><p id="split"></p><div class="scroll"><table><thead><tr><th>模型</th><th>Precision</th><th>Recall</th><th>F1</th><th>AUC</th></tr></thead><tbody id="scores"></tbody></table></div><p id="failures"></p><p><a href="artifacts/REPORT.md">报告</a> · <a href="artifacts/results.json">原始结果</a> · <a href="README.md">复现与边界</a></p><p class="warning">去重后再分集；阈值只看验证集；误判全部保留。测试高分不代表真实用户泛化。</p></section>'''
 js='''const m=data.model,r=data.results;function norm(t){return (t.toLowerCase().replace(/https?:\\/\\/\\S+|www\\.\\S+/g,' urltoken ').replace(/\\S+@\\S+/g,' emailtoken ').replace(/\\d+/g,' numbertoken ').match(/[a-z]+/g)||[]);}function infer(t){const w=norm(t),terms=w.concat(w.slice(0,-1).map((x,i)=>x+' '+w[i+1])),counts=new Map();terms.forEach(t=>counts.set(t,(counts.get(t)||0)+1));const v=[];counts.forEach((c,t)=>{if(Object.prototype.hasOwnProperty.call(m.vocabulary,t)){const i=m.vocabulary[t];v.push({t,i,x:c*m.idf[i]});}});const n=Math.sqrt(v.reduce((s,e)=>s+e.x*e.x,0));const z=m.intercept+v.reduce((s,e)=>s+(n?e.x/n:0)*m.coef[e.i],0);const p=1/(1+Math.exp(-z));return {p,v:v.map(e=>({...e,contribution:n?e.x/n*m.coef[e.i]:0})),review:!n||Math.abs(p-m.threshold)<.15};}function predict(){if($('input').value.length>5000){$('status').textContent='输入须小于5000字符';return;}const x=infer($('input').value);$('prob').textContent=(x.p*100).toFixed(1)+'%';$('status').textContent=(x.p>=m.threshold?'模型倾向：spam':'模型倾向：ham')+(x.review?' · 建议人工复核':' · 非安全保证');$('terms').replaceChildren();x.v.sort((a,b)=>Math.abs(b.contribution)-Math.abs(a.contribution)).slice(0,6).forEach(e=>$('terms').append(text('div',e.t+' / logit contribution '+e.contribution.toFixed(3))));}r.examples.forEach((e,i)=>{const op=text('option',e.text);op.value=i;$('examples').append(op);});$('examples').addEventListener('change',()=>{$('input').value=r.examples[Number($('examples').value)].text;predict();});$('predict').addEventListener('click',predict);table('scores',r.test_results.map(m=>[m.model,...['precision','recall','f1','roc_auc'].map(k=>m.test[k].toFixed(4))]));$('split').textContent='训练 / 验证 / 测试：'+['train','validation','test'].map(k=>r.split[k].length).join(' / ');$('failures').textContent='Logistic 测试误判 '+r.failure_ids.length+' 个；导出参数推断最大误差 '+r.export_parity_max_error.toExponential(2);predict();'''
 build('textguard','TextGuard｜可解释文本分类','真实 TF-IDF＋Logistic 训练；本页直接执行已导出的模型参数，不是模拟预测。',body,js,tg)
 nv={'model':read('novelty-lab','model.json'),'results':read('novelty-lab','results.json')}
 body='''<section class="card"><h2>13 维数值输入 · 本地距离模型</h2><select id="examples" aria-label="样本选择"></select><textarea id="input" aria-label="13维数值JSON数组"></textarea><button id="predict">计算新颖性</button><p id="status" role="status"></p><div class="metric" id="score"></div><div id="features"></div><p class="warning">Wine 类别 0 作为正常分布，其他类别作为迁移。不是工业异常标签、欺诈检测或医疗判断；距离不是概率。</p></section><section class="card"><h2>模型对照 · 固定测试</h2><p id="split"></p><div class="scroll"><table><thead><tr><th>模型</th><th>AUC</th><th>PR-AUC</th><th>Recall</th><th>正常误报</th></tr></thead><tbody id="scores"></tbody></table></div><p><a href="artifacts/REPORT.md">报告</a> · <a href="artifacts/results.json">原始结果</a> · <a href="README.md">复现与边界</a></p><p class="warning">标准化仅拟合正常训练；阈值仅正常验证 95 分位；默认距离模型预先固定，不按测试最高分选型。正常留出只有12个，误报0不意味着生产零误报。</p></section>'''
 js='''const m=data.model,r=data.results;function predict(){try{const x=JSON.parse($('input').value);if(!Array.isArray(x)||x.length!==13||!x.every(v=>typeof v==='number'&&Number.isFinite(v)))throw Error('需要13个有限数字');const z=x.map((v,i)=>(v-m.mean[i])/m.scale[i]);const score=Math.sqrt(z.reduce((s,v,i)=>s+(v-m.center[i])**2,0));$('score').textContent=score.toFixed(3);$('status').textContent=(score>m.threshold?'超过本地新颖性阈值':'处于参考范围')+' / 阈值 '+m.threshold.toFixed(3);$('features').replaceChildren();z.map((v,i)=>({i,v})).sort((a,b)=>Math.abs(b.v)-Math.abs(a.v)).slice(0,3).forEach(e=>$('features').append(text('div',m.feature_names[e.i]+' / standardized deviation '+e.v.toFixed(3))));}catch(e){$('status').textContent=e.message;$('score').textContent='—';}}r.examples.forEach((e,i)=>{const op=text('option','公开数据行 '+e.row+' / 类别 '+e.actual_class);op.value=i;$('examples').append(op);});function example(){$('input').value=JSON.stringify(r.examples[Number($('examples').value)].values);predict();}$('examples').addEventListener('change',example);$('predict').addEventListener('click',predict);table('scores',r.results.map(e=>[e.model,...['roc_auc','average_precision','recall','false_positive_rate'].map(k=>e.test[k].toFixed(4))]));$('split').textContent='正常训练 '+r.split.train.length+' / 正常验证 '+r.split.validation.length+' / 总测试 '+r.split.test.length;example();'''
 build('novelty-lab','NoveltyLab｜多变量分布迁移检测','实际拟合距离、Isolation Forest 和 One-Class SVM；本页执行可解释距离基线。',body,js,nv)
 rag=read('cite-rag','results.json')
 body='''<section class="card"><h2>引用优先问答 · 本地摘录</h2><textarea id="input" aria-label="英文知识问题">retry transient bounded attempts</textarea><select id="method" aria-label="检索方法"><option value="hybrid">RRF 混合</option><option value="bm25">BM25</option><option value="char">字符余弦</option></select><button id="ask">检索与摘录</button><select id="examples" aria-label="问题示例"></select><p id="status" role="status"></p><div id="answer"></div><div id="hits"></div><p class="warning">本页不是 LLM 生成；只摘录现有证据。真实大模型接口已实现但未配置、未调用评测；密钥不得放网页。</p></section><section class="card"><h2>困难问题和拒答单列</h2><div class="scroll"><table><thead><tr><th>方法</th><th>集合</th><th>Recall@3</th><th>MRR@3</th><th>拒答正确率</th></tr></thead><tbody id="scores"></tbody></table></div><p><a href="artifacts/REPORT.md">报告</a> · <a href="artifacts/results.json">原始结果</a> · <a href="README.md">真实 LLM 配置说明</a></p><p class="warning">自建15篇说明25个问题，共享 FlowBench 知识片段；数据小且有作者偏差。混合召回不保证更准，引用ID正确不代表语义支持。</p></section>'''
 js='''const docs=data.documents;const words=t=>t.toLowerCase().match(/[a-z0-9]+/g)||[];function count(a){const m=new Map();a.forEach(x=>m.set(x,(m.get(x)||0)+1));return m;}function grams(t){const x=words(t).join(' '),a=[];for(let i=0;i<x.length-2;i++)a.push(x.slice(i,i+3));return count(a);}const freq=docs.map(d=>count(words(d.text))),avg=freq.reduce((s,f)=>s+[...f.values()].reduce((a,b)=>a+b,0),0)/docs.length;function rank(q,method){const cq=grams(q),normq=[...cq.values()].reduce((s,v)=>s+v*v,0);let rows=docs.map((d,i)=>{const f=freq[i],len=[...f.values()].reduce((a,b)=>a+b,0);let lexical=0;new Set(words(q)).forEach(t=>{const tf=f.get(t)||0,df=freq.filter(x=>x.has(t)).length;lexical+=tf?Math.log(1+(docs.length-df+.5)/(df+.5))*tf*2.2/(tf+1.2*(.25+.75*len/avg)):0;});const cd=grams(d.text),norm=Math.sqrt(normq*[...cd.values()].reduce((s,v)=>s+v*v,0));let dot=0;cq.forEach((v,k)=>dot+=v*(cd.get(k)||0));return {...d,lexical,char:norm?dot/norm:0,score:0};});const sort=k=>[...rows].sort((a,b)=>b[k]-a[k]||a.id.localeCompare(b.id));if(method==='hybrid'){['lexical','char'].forEach(k=>sort(k).forEach((r,i)=>{if(r[k]>0)rows.find(x=>x.id===r.id).score+=1/(61+i);}));}else rows.forEach(r=>r.score=r[method==='bm25'?'lexical':'char']);return rows.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id));}function ask(){const q=$('input').value;if(!q.trim()||q.length>2000){$('status').textContent='需要1–2000字符问题';return;}const hits=rank(q,$('method').value).slice(0,3),support=Math.max(...hits.map(h=>h.lexical))>=1.5||Math.max(...hits.map(h=>h.char))>=.35;$('status').textContent=support?'本地摘录 / 未调用 LLM':'证据不足，拒答';$('answer').textContent=support?hits[0].text+' [引用 '+hits[0].id+']':'Insufficient evidence in this knowledge pack.';$('hits').replaceChildren();hits.forEach(h=>{const el=text('div',h.id+' / score '+h.score.toFixed(4)+' / '+h.text);el.className='trace';$('hits').append(el);});}data.examples.forEach((e,i)=>{const op=text('option',e.q);op.value=i;$('examples').append(op);});$('examples').addEventListener('change',()=>{$('input').value=data.examples[Number($('examples').value)].q;ask();});$('ask').addEventListener('click',ask);const fmt=v=>v===null?'—':v.toFixed(3);table('scores',data.metrics.map(m=>[m.method,m.split,fmt(m.recall3),fmt(m.mrr3),fmt(m.refusal_accuracy)]));ask();'''
 build('cite-rag','CiteRAG｜可追溯检索问答','BM25、字符检索与 RRF 对照；本地摘录、引用核验、证据不足拒答。真实 LLM 需另行配置。',body,js,rag)
 print('Built 3 self-contained real-inference demos')
if __name__=='__main__':main()
